/// 🧾️ Trusted durable-boundary witness returned only after the decision transaction is synced.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct DurableOwnedGroupJournalReceiptV1 {
    pub anchor_sha256: String,
    pub decision_sha256: String,
    pub transaction_id: u64,
    pub segment_index: u64,
}

/// 🔐️ Store-admitted decision event whose private bytes and identities can only come from
/// one fully verified canonical fixed-three decision Pack.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct DurableOwnedGroupJournalRecordV1 {
    canonical_pack: Vec<u8>,
    decision_sha256: String,
    anchor_sha256: String,
    document: semio_framework_artifact_reference::ArtifactRef,
    parent_edit_id: String,
    parent_post_revision: [u8; 32],
}

/// 🔎️ Immutable typed edits projected only after Store verifies every bound fixed-three outcome.
pub struct DurableOwnedGroupVerifiedThreeEditsV1<ParentMutation, DrawingMutation, ValueMutation> {
    decision_sha256: String,
    anchor_sha256: String,
    document: semio_framework_artifact_reference::ArtifactRef,
    parent: Edit<ParentMutation>,
    drawing: Edit<DrawingMutation>,
    value: Edit<ValueMutation>,
}

impl<ParentMutation, DrawingMutation, ValueMutation> DurableOwnedGroupVerifiedThreeEditsV1<ParentMutation, DrawingMutation, ValueMutation> {
    pub fn decision_sha256(&self) -> &str {
        &self.decision_sha256
    }

    pub fn anchor_sha256(&self) -> &str {
        &self.anchor_sha256
    }

    pub fn document(&self) -> &semio_framework_artifact_reference::ArtifactRef {
        &self.document
    }

    pub fn parent(&self) -> &Edit<ParentMutation> {
        &self.parent
    }

    pub fn drawing(&self) -> &Edit<DrawingMutation> {
        &self.drawing
    }

    pub fn value(&self) -> &Edit<ValueMutation> {
        &self.value
    }
}

impl DurableOwnedGroupJournalRecordV1 {
    /// 🔏️ Admits one canonical decision Pack and derives its decision identity exclusively from
    /// the Store-verified fixed-three envelope.
    pub fn admit_canonical(canonical_pack: Vec<u8>) -> Result<Self, DurableOwnedGroupDecisionError> {
        let decision = DurableOwnedThreeMemberDecisionV1::decode_canonical_pack(&canonical_pack)?;
        let parent = DurableBoundOneItemOutcomeV1::decode_canonical_pack(&decision.parent.recovery_pack)?;
        let edit: DslValue = parse_canonical_json_value(&parent.edit_canonical_json)?;
        let parent_edit_id = edit.get("id").and_then(semio_framework_value::DslValue::as_str).filter(|identity| !identity.is_empty() && identity.len() <= DURABLE_OWNED_GROUP_ID_MAX_BYTES).ok_or(DurableOwnedGroupDecisionError::InvalidIdentity)?.to_string();
        if decision.parent.post_revision == [0; 32] {
            return Err(DurableOwnedGroupDecisionError::InvalidFrontier);
        }
        Ok(Self { canonical_pack, decision_sha256: decision.decision_sha256, anchor_sha256: decision.anchor_sha256, document: decision.anchor.parent, parent_edit_id, parent_post_revision: decision.parent.post_revision })
    }

    pub fn admit(canonical_pack: Vec<u8>, claimed_decision_sha256: &str) -> Result<Self, DurableOwnedGroupDecisionError> {
        let record = Self::admit_canonical(canonical_pack)?;
        if record.decision_sha256 != claimed_decision_sha256 {
            return Err(DurableOwnedGroupDecisionError::InvalidHash);
        }
        Ok(record)
    }

    pub fn canonical_pack(&self) -> &[u8] {
        &self.canonical_pack
    }

    pub fn into_canonical_pack(self) -> Vec<u8> {
        self.canonical_pack
    }

    pub fn decision_sha256(&self) -> &str {
        &self.decision_sha256
    }

    pub fn anchor_sha256(&self) -> &str {
        &self.anchor_sha256
    }

    pub fn document(&self) -> &semio_framework_artifact_reference::ArtifactRef {
        &self.document
    }

    /// 📍️ Projects the parent edit identity only from the fully admitted bound outcome.
    pub fn parent_edit_id(&self) -> &str {
        &self.parent_edit_id
    }

    /// 🧬️ Projects the exact parent Store revision after the fixed-three visibility flip.
    pub fn parent_post_revision(&self) -> [u8; 32] {
        self.parent_post_revision
    }

    pub fn into_parts(self) -> (Vec<u8>, String, String, semio_framework_artifact_reference::ArtifactRef) {
        (self.canonical_pack, self.decision_sha256, self.anchor_sha256, self.document)
    }

    /// 🧬️ Re-admits the complete decision and verifies all three typed bound outcomes before
    /// exposing immutable edit projections; no publication seal or binding authority escapes.
    pub fn verify_fixed_three_edits<ParentP, ParentMutation, DrawingP, DrawingMutation, ValueP, ValueMutation>(&self) -> Result<DurableOwnedGroupVerifiedThreeEditsV1<ParentMutation, DrawingMutation, ValueMutation>, DurableOwnedGroupDecisionError>
    where
        ParentP: ArtifactPack,
        ParentMutation: ValueToValue + ValueFromValue,
        DrawingP: ArtifactPack,
        DrawingMutation: ValueToValue + ValueFromValue,
        ValueP: ArtifactPack,
        ValueMutation: ValueToValue + ValueFromValue,
    {
        let decision = DurableOwnedThreeMemberDecisionV1::decode_canonical_pack(&self.canonical_pack)?;
        if decision.decision_sha256 != self.decision_sha256 || decision.anchor_sha256 != self.anchor_sha256 || decision.anchor.parent != self.document {
            return Err(DurableOwnedGroupDecisionError::InvalidHash);
        }
        Ok(DurableOwnedGroupVerifiedThreeEditsV1 {
            parent: verify_bound_member_edit::<ParentP, ParentMutation>(&decision.parent, &decision.decision_sha256)?,
            drawing: verify_bound_member_edit::<DrawingP, DrawingMutation>(&decision.drawing, &decision.decision_sha256)?,
            value: verify_bound_member_edit::<ValueP, ValueMutation>(&decision.value, &decision.decision_sha256)?,
            decision_sha256: decision.decision_sha256,
            anchor_sha256: decision.anchor_sha256,
            document: decision.anchor.parent,
        })
    }

    /// ♻️ Reconstructs only Store-private sealed owners from one committed decision and the exact three retained live Stores.
    fn begin_store_owned_recovery<ParentP, ParentMutation, DrawingP, DrawingMutation, ValueP, ValueMutation>(
        &self,
        receipt: DurableOwnedGroupJournalReceiptV1,
        parent: ArtifactStore<ParentP, ParentMutation>,
        drawing: ArtifactStore<DrawingP, DrawingMutation>,
        value: ArtifactStore<ValueP, ValueMutation>,
    ) -> Result<DurableOwnedMapRecoveryStartV1<ParentP, ParentMutation, DrawingP, DrawingMutation, ValueP, ValueMutation>, DurableOwnedMapRecoveryRejectedV1<ParentP, ParentMutation, DrawingP, DrawingMutation, ValueP, ValueMutation>>
    where
        ParentP: ArtifactPack + Clone + ValueToValue + ValueFromValue + Send + Sync + 'static,
        ParentMutation: StoreMutation<ParentP> + Clone + ValueToValue + ValueFromValue + Send + 'static,
        DrawingP: ArtifactPack + Clone + ValueToValue + ValueFromValue + Send + Sync + 'static,
        DrawingMutation: StoreMutation<DrawingP> + Clone + ValueToValue + ValueFromValue + Send + 'static,
        ValueP: ArtifactPack + Clone + ValueToValue + ValueFromValue + Send + Sync + 'static,
        ValueMutation: StoreMutation<ValueP> + Clone + ValueToValue + ValueFromValue + Send + 'static,
    {
        let rejected = |error, parent, drawing, value| DurableOwnedMapRecoveryRejectedV1 { error, parent, drawing, value };
        let decision = match DurableOwnedThreeMemberDecisionV1::decode_canonical_pack(&self.canonical_pack) {
            Ok(decision) if decision.decision_sha256 == self.decision_sha256 && decision.anchor_sha256 == self.anchor_sha256 && decision.anchor.parent == self.document => decision,
            Ok(_) => return Err(rejected(DurableOwnedGroupDecisionError::InvalidHash, parent, drawing, value)),
            Err(error) => return Err(rejected(error, parent, drawing, value)),
        };
        if receipt.decision_sha256 != self.decision_sha256 || receipt.anchor_sha256 != self.anchor_sha256 || receipt.transaction_id == 0 {
            return Err(rejected(DurableOwnedGroupDecisionError::InvalidHash, parent, drawing, value));
        }
        match decision.recover_store_owned(&parent, &drawing, &value) {
            Ok(DurableOwnedThreeStoreRecoveryV1::AlreadyApplied) => Ok(DurableOwnedMapRecoveryStartV1::AlreadyApplied(DurableOwnedMapRecoveryOwnersV1 { parent, drawing, value })),
            Ok(DurableOwnedThreeStoreRecoveryV1::Apply(bound)) => match bound.begin_retained_recovery(receipt) {
                Ok(coordinator) => Ok(DurableOwnedMapRecoveryStartV1::Apply(DurableOwnedMapRecoveryHostV1 {
                    operation: std::mem::ManuallyDrop::new(Some(DurableOwnedMapRecoveryOperationV1 {
                        parent: std::mem::ManuallyDrop::new(Some(parent)),
                        drawing: std::mem::ManuallyDrop::new(Some(drawing)),
                        value: std::mem::ManuallyDrop::new(Some(value)),
                        coordinator: std::mem::ManuallyDrop::new(Some(coordinator)),
                    })),
                })),
                Err(error) => Err(rejected(error, parent, drawing, value)),
            },
            Err(error) => Err(rejected(error, parent, drawing, value)),
        }
    }
}

/// 🧭️ One retained journal turn. `Rejected` proves that no mailbox/WAL transfer began,
/// while `Absent` proves an accepted cancellation left no durable record. An error remains an
/// uncertain external state and must be resolved by the same retained owner.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum DurableOwnedGroupJournalAdvanceV1 {
    Pending,
    Absent,
    Rejected(String),
    Committed(DurableOwnedGroupJournalReceiptV1),
}

/// 🧯️ Retained, cancellable owner for one durable decision attempt and its recovery resolution.
pub trait DurableOwnedGroupJournalCommitV1: Send {
    fn advance(&mut self, grant: super::ArtifactStoreOneItemGrant) -> Result<DurableOwnedGroupJournalAdvanceV1, String>;
    fn cancel(&mut self);
    fn begin_close(&mut self);
    fn close_step(&mut self, grant: super::ArtifactStoreOneItemGrant) -> Result<super::SnapshotRetirementStep, semio_framework_value::ValueError>;
    fn terminal_is_empty(&self) -> bool;
}

/// 🗄️ Kernel-owned journal port implemented by a storage owner with an exclusive writer permit.
/// Construction is an infallible, non-I/O owner transfer; every fallible or externally visible
/// journal action begins in the returned retained operation's first `advance` turn.
pub trait DurableOwnedGroupJournalSinkV1: Send {
    fn begin_commit(&mut self, decision_pack: Vec<u8>, decision_sha256: String) -> Box<dyn DurableOwnedGroupJournalCommitV1>;
}

pub(super) struct ArtifactStoreDurableGroupRootV1<P> {
    pub(super) visibility: Arc<crate::os_vcs::ArtifactGroupVisibility>,
    pub(super) current: Option<Arc<P>>,
    pub(super) generation: u64,
    pub(super) content_revision: [u8; 32],
    pub(super) applied_edit_ids: crate::os_vcs::HistoryPageStack<String>,
    pub(super) redo_edit_ids: crate::os_vcs::HistoryPageStack<String>,
    pub(super) last_projection_cause: Option<super::ArtifactProjectionCause>,
    edit_sequence: i32,
    clock: HybridLogicalTimestamp,
    pub(super) revision_accumulator: Option<CursorRevisionAccumulator>,
    tail_undo_cache: Option<(String, Arc<P>)>,
    authority: Option<Arc<ArtifactStoreOneItemLiveAuthority>>,
    displaced_reservation: Option<super::ArtifactStoreDisplacedOwnerReservation>,
    retirement: Option<Box<StagedRootRetirement<P>>>,
    pub(super) adopted: bool,
}

pub(super) struct StagedRootRetirement<P> {
    cursor: Option<super::ArtifactStoreCursorRetirement>,
    applied: Option<super::ArtifactStoreStringVectorRetirement>,
    redo: Option<super::ArtifactStoreStringVectorRetirement>,
    revision: Option<super::ArtifactStoreRevisionAccumulatorRetirement>,
    report: Option<super::ArtifactStorePendingReportRetirement>,
    tail_id: Option<super::ArtifactStoreStringRetirement>,
    authority: Option<super::canonical_edit::ArtifactStoreOneItemAuthorityRetirement>,
    snapshots: [Option<Arc<P>>; 2],
    active: Option<Box<dyn super::ErasedSnapshotRetirement>>,
    factory: Option<Arc<dyn super::SnapshotRetirementFactory<P>>>,
    phase: u8,
}

impl<P> StagedRootRetirement<P> {
    fn new(factory: Arc<dyn super::SnapshotRetirementFactory<P>>) -> Self {
        Self { cursor: None, applied: None, redo: None, revision: None, report: None, tail_id: None, authority: None, snapshots: [None, None], active: None, factory: Some(factory), phase: 0 }
    }

    fn inline_owner(&self) -> Option<&dyn super::ErasedSnapshotRetirement> {
        match self.phase {
            0 => self.cursor.as_ref().map(|owner| owner as _),
            1 => self.applied.as_ref().map(|owner| owner as _),
            2 => self.redo.as_ref().map(|owner| owner as _),
            3 => self.revision.as_ref().map(|owner| owner as _),
            4 => self.report.as_ref().map(|owner| owner as _),
            5 => self.tail_id.as_ref().map(|owner| owner as _),
            6 => self.authority.as_ref().map(|owner| owner as _),
            _ => None,
        }
    }

    fn inline_owner_mut(&mut self) -> Option<&mut dyn super::ErasedSnapshotRetirement> {
        match self.phase {
            0 => self.cursor.as_mut().map(|owner| owner as _),
            1 => self.applied.as_mut().map(|owner| owner as _),
            2 => self.redo.as_mut().map(|owner| owner as _),
            3 => self.revision.as_mut().map(|owner| owner as _),
            4 => self.report.as_mut().map(|owner| owner as _),
            5 => self.tail_id.as_mut().map(|owner| owner as _),
            6 => self.authority.as_mut().map(|owner| owner as _),
            _ => None,
        }
    }

    fn clear_inline(&mut self) {
        match self.phase {
            0 => { self.cursor = None; }
            1 => { self.applied = None; }
            2 => { self.redo = None; }
            3 => { self.revision = None; }
            4 => { self.report = None; }
            5 => { self.tail_id = None; }
            6 => { self.authority = None; }
            _ => {}
        }
    }
}

impl<P: Send + Sync> super::ErasedSnapshotRetirement for StagedRootRetirement<P> {
    fn next_close_byte_demand(&self) -> usize {
        if let Some(active) = self.active.as_ref() { return super::artifact_retirement_box_byte_demand(active); }
        if let Some(owner) = self.inline_owner() { return owner.next_close_byte_demand(); }
        if (7..9).contains(&self.phase) {
            if let Some(snapshot) = self.snapshots[usize::from(self.phase - 7)].as_ref() {
                return self.factory.as_ref().expect("staged root retains its snapshot factory").retirement_birth_bytes(snapshot);
            }
        }
        0
    }

    fn close_step(&mut self, items: usize, bytes: usize) -> Result<super::SnapshotRetirementStep, semio_framework_value::ValueError> {
        use super::{ErasedSnapshotRetirement as _, SnapshotRetirementStep};
        if items == 0 || bytes < self.next_close_byte_demand() { return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 }); }
        if self.active.is_some() { return super::artifact_retirement_box_close_step(&mut self.active, items, bytes); }
        if let Some(owner) = self.inline_owner_mut() {
            let step = owner.close_step(items, bytes)?;
            if step != SnapshotRetirementStep::Complete { return Ok(step); }
            if !owner.terminal_is_empty() { return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "staged root inline retirement lost its terminal witness")); }
            self.clear_inline();
        }
        if (7..9).contains(&self.phase) {
            if let Some(snapshot) = self.snapshots[usize::from(self.phase - 7)].take() {
                self.active = Some(self.factory.as_ref().expect("staged root retains its snapshot factory").retire(snapshot));
                return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
            }
        }
        if self.phase < 9 {
            self.phase += 1;
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        self.factory = None;
        Ok(SnapshotRetirementStep::Complete)
    }

    fn terminal_is_empty(&self) -> bool {
        self.cursor.is_none() && self.applied.is_none() && self.redo.is_none() && self.revision.is_none() && self.report.is_none() && self.tail_id.is_none() && self.authority.is_none() && self.snapshots.iter().all(Option::is_none) && self.active.is_none() && self.factory.is_none()
    }
}

impl<P> Drop for StagedRootRetirement<P> {
    fn drop(&mut self) {
        assert!(std::thread::panicking() || (self.cursor.is_none() && self.applied.is_none() && self.redo.is_none() && self.revision.is_none() && self.report.is_none() && self.tail_id.is_none() && self.authority.is_none() && self.snapshots.iter().all(Option::is_none) && self.active.is_none() && self.factory.is_none()), "staged root retirement dropped before all exact outgoing owners were closed");
    }
}

fn retained_string_stack(source: impl IntoIterator<Item = String>, appended: Option<&str>) -> Result<crate::os_vcs::HistoryPageStack<String>, DurableOwnedGroupDecisionError> {
    let mut values = crate::os_vcs::HistoryPageStack::try_new().map_err(|error| DurableOwnedGroupDecisionError::Codec(error.into()))?;
    for value in source {
        values.try_push(value).map_err(|_| DurableOwnedGroupDecisionError::Codec("history catalog address space exhausted".into()))?;
    }
    if let Some(value) = appended {
        values.try_push(value.to_string()).map_err(|_| DurableOwnedGroupDecisionError::Codec("history catalog address space exhausted".into()))?;
    }
    Ok(values)
}

fn retained_revision_stack(source: impl IntoIterator<Item = super::CursorRevisionRecord>) -> Result<crate::os_vcs::HistoryPageStack<super::CursorRevisionRecord>, DurableOwnedGroupDecisionError> {
    let mut values = crate::os_vcs::HistoryPageStack::try_new().map_err(|error| DurableOwnedGroupDecisionError::Codec(error.into()))?;
    for value in source {
        values.try_push(value).map_err(|_| DurableOwnedGroupDecisionError::Codec("history catalog address space exhausted".into()))?;
    }
    Ok(values)
}

fn stage_store_member<P, Mutation>(
    store: &mut ArtifactStore<P, Mutation>,
    outcome: DurableStoreBoundOutcomeV1<P, Mutation>,
    visibility: &Arc<crate::os_vcs::ArtifactGroupVisibility>,
) -> Result<(), (DurableOwnedGroupDecisionError, DurableStoreBoundOutcomeV1<P, Mutation>)>
where
    P: ArtifactPack + Clone + ValueToValue + ValueFromValue + Send + Sync + 'static,
    Mutation: StoreMutation<P> + Clone + ValueToValue + ValueFromValue + Send + 'static,
{
    let reject = |reason, outcome| Err((reason, outcome));
    if store.durable_group_root.is_some()
        || !visibility.pending()
        || store.backbone.is_some()
        || store.snapshot_retirement_factory.is_none()
        || store.mutation_retirement_factory.is_none()
        || store.envelope.vcs.edits.group_visibility().is_some()
        || store.envelope.cursor.as_ref().is_none_or(|cursor| cursor.group_visibility().is_some())
    {
        return reject(DurableOwnedGroupDecisionError::InvalidFrontier, outcome);
    }
    if outcome.prepared.seal.authority.validate_prepared(&outcome.prepared).is_err()
        || store.generation != outcome.expected_generation
        || store.content_revision != outcome.expected_revision
        || outcome.expected_generation.checked_add(1) != Some(outcome.post_generation)
        || outcome.prepared.seal.authority.generation.0 != outcome.expected_generation
        || outcome.prepared.seal.authority.base_revision != outcome.expected_revision
        || outcome.prepared.seal.authority.base_applied_edit_count != store.applied_edit_ids.len()
        || outcome.prepared.edit.id != outcome.prepared.applied_edit_id
        || outcome.prepared.edit.id != outcome.prepared.tail_edit_id
        || outcome.prepared.edit.sequence_number != outcome.prepared.seal.authority.next_sequence_number
        || outcome.prepared.next_clock != outcome.prepared.seal.authority.next_clock
        || !store.applied_edit_ids.admits_one()
    {
        return reject(DurableOwnedGroupDecisionError::InvalidOutcome, outcome);
    }
    let group_id = outcome.prepared.seal.authority.group_id.as_deref().unwrap_or_default();
    if !valid_hash(group_id) || outcome.prepared.edit.mutation_meta.first().and_then(|meta| meta.group_id.as_deref()) != Some(group_id) {
        return reject(DurableOwnedGroupDecisionError::InvalidHash, outcome);
    }
    let applied_edit_ids = match retained_string_stack(store.applied_edit_ids.iter().cloned(), Some(&outcome.prepared.edit.id)) {
        Ok(values) => values,
        Err(error) => return reject(error, outcome),
    };
    let redo_edit_ids = match retained_string_stack(std::iter::empty(), None) {
        Ok(values) => values,
        Err(error) => return reject(error, outcome),
    };
    let cursor_owners = super::ArtifactCursorOwners {
        applied_edit_ids: match retained_string_stack(store.applied_edit_ids.iter().cloned(), Some(&outcome.prepared.edit.id)) {
            Ok(values) => values,
            Err(error) => return reject(error, outcome),
        },
        redo_edit_ids: match retained_string_stack(std::iter::empty(), None) {
            Ok(values) => values,
            Err(error) => return reject(error, outcome),
        },
        checkpoint_id: (*store.current_checkpoint_id).clone(),
    };
    let mut revision_accumulator = CursorRevisionAccumulator {
        identity_digest: store.revision_accumulator.identity_digest,
        applied: match retained_revision_stack(store.revision_accumulator.applied.iter().cloned()) {
            Ok(values) => values,
            Err(error) => return reject(error, outcome),
        },
        redo: match retained_revision_stack(std::iter::empty()) {
            Ok(values) => values,
            Err(error) => return reject(error, outcome),
        },
        applied_tail_chains: None,
        mutation_positions: store.revision_accumulator.mutation_positions.clone(),
        indexed_edits: store.revision_accumulator.indexed_edits.clone(),
        unit_flags: store.revision_accumulator.unit_flags.clone(),
    };
    revision_accumulator.index_applied_edit::<P, Mutation>(applied_edit_ids.len() - 1, &outcome.prepared.edit);
    let edit_digest = CursorRevisionAccumulator::hash_record(b"edit-id", &[outcome.prepared.edit.id.as_bytes()]);
    for (index, operation) in outcome.prepared.edit.forwards.iter().enumerate().filter(|(_, op)| op.may_emit_foreign_steps()) {
        revision_accumulator.unit_flags.insert((edit_digest, index), !operation.foreign_steps(&store.current).is_empty());
    }
    let previous = revision_accumulator.applied.last().map_or(revision_accumulator.identity_digest, |record| record.prefix_digest);
    revision_accumulator.applied.push(super::CursorRevisionRecord {
        ledger_key: None,
        id_digest: CursorRevisionAccumulator::hash_record(b"edit-id", &[outcome.prepared.edit.id.as_bytes()]),
        edit_digest: outcome.prepared.edit_digest,
        prefix_digest: CursorRevisionAccumulator::hash_record(b"applied", &[&previous, &outcome.prepared.edit_digest]),
    });
    if revision_accumulator.revision(store.current_checkpoint_id.as_deref()) != outcome.post_revision {
        return reject(DurableOwnedGroupDecisionError::InvalidFrontier, outcome);
    }
    let displaced_reservation = match store.displaced_retirements.reserve_owner_slots(12) {
        Ok(reservation) => reservation,
        Err(_) => return reject(DurableOwnedGroupDecisionError::InvalidFrontier, outcome),
    };
    let history_reservation = match store.envelope.vcs.edits.reserve_group_one(visibility) {
        Ok(reservation) => reservation,
        Err(_) => {
            store.displaced_retirements.release_owner_slots(displaced_reservation).expect("unconsumed durable group retirement reservation remains exact");
            return reject(DurableOwnedGroupDecisionError::InvalidFrontier, outcome);
        }
    };
    store.envelope.cursor.as_mut().expect("durable group stage preflight retained its cursor").stage_group_owned(cursor_owners, visibility).expect("durable group cursor stage remains exact after exclusive preflight");
    let post_revision = outcome.post_revision;
    let DurableStoreBoundOutcomeV1 { prepared, .. } = outcome;
    let ArtifactStoreOneItemPrepared { edit, post_snapshot, next_clock, edit_digest: _, local_actor, applied_edit_id: _, tail_edit_id, seal } = prepared;
    if let Some(actor) = local_actor {
        store.displaced_retirements.push_reserved(Box::new(super::ArtifactStoreStringRetirement::new(actor)));
    }
    let ledger_key = store.envelope.vcs.edits.stage_group_reserved(history_reservation, *edit, visibility).unwrap_or_else(|_| panic!("durable group history stage remains exact after its exclusive reservation"));
    let mut tail = revision_accumulator.applied.pop().expect("staged revision retains its exact tail");
    tail.ledger_key = Some(ledger_key);
    revision_accumulator.applied.push(tail);
    *store.durable_group_root = Some(ArtifactStoreDurableGroupRootV1 {
        visibility: Arc::clone(visibility),
        current: Some(post_snapshot),
        generation: store.generation + 1,
        content_revision: post_revision,
        applied_edit_ids,
        redo_edit_ids,
        last_projection_cause: Some(super::ArtifactProjectionCause::Apply),
        edit_sequence: seal.authority.next_sequence_number,
        clock: next_clock,
        revision_accumulator: Some(revision_accumulator),
        tail_undo_cache: Some((tail_edit_id, Arc::clone(&store.current))),
        authority: Some(seal.authority),
        displaced_reservation: Some(displaced_reservation),
        retirement: Some(Box::new(StagedRootRetirement::new(Arc::clone(store.snapshot_retirement_factory.as_ref().expect("staged group retains its snapshot factory"))))),
        adopted: false,
    });
    Ok(())
}

/// 🧱️ Transfers already copied catalogs and exact reserved owners without traversing history.
pub(super) fn stage_prebuilt_batch_root<P, Mu>(store: &mut ArtifactStore<P, Mu>, publication: &mut super::ArtifactStoreBatchPublication<P, Mu>) -> Result<(), String>
where P: ArtifactPack + Clone + ValueToValue + ValueFromValue + Send + Sync + 'static,
      Mu: StoreMutation<P> + Clone + ValueToValue + ValueFromValue + Send + 'static,
{
    if store.durable_group_root.is_some() || store.envelope.cursor.as_ref().is_none_or(|cursor| cursor.group_visibility().is_some()) { return Err("batch group final root transfer lost its exclusive cursor frontier".into()); }
    store.generation.checked_add(1).ok_or_else(|| "batch group generation is exhausted".to_string())?;
    let authority = Arc::clone(publication.authority.as_ref().ok_or_else(|| "batch group final transfer lost its authority".to_string())?);
    let group = publication.group_preparation.as_mut().ok_or_else(|| "batch group final transfer lost its retained preparation".to_string())?;
    let visibility = group.visibility();
    let history = group.history.as_ref().ok_or_else(|| "batch group final transfer lost its history reservation".to_string())?;
    store.envelope.vcs.edits.bind_group_reservation(&history.history, &visibility).map_err(|()| "batch group history reservation is stale".to_string())?;
    let history = group.history.take().ok_or_else(|| "batch group final transfer lost its history reservation".to_string())?;
    let mut displaced = group.displaced.take().expect("copied group admits its displaced owner catalog");
    let cursor = super::ArtifactCursorOwners { applied_edit_ids: std::mem::replace(&mut group.cursor, crate::os_vcs::HistoryPageStack::empty()), redo_edit_ids: crate::os_vcs::HistoryPageStack::empty(), checkpoint_id: group.checkpoint.take() };
    let applied = std::mem::replace(&mut group.applied, crate::os_vcs::HistoryPageStack::empty());
    let mut revision = group.revision.take().expect("copied group retains its complete revision and indexes");
    let stage = publication.take_stage().expect("copied group retains its complete typed candidate");
    let super::ArtifactStoreBatchStage { edit, post, next_clock, local_actor, applied_edit_id, tail_edit_id, .. } = *stage;
    store.envelope.cursor.as_mut().expect("exclusive group transfer retains its cursor").stage_group_owned(cursor, &visibility).unwrap_or_else(|_| panic!("exclusive copied group cursor transfer must retain its exact owners"));
    let ledger = store.envelope.vcs.edits.stage_group_reserved(history.history, *edit, &visibility).unwrap_or_else(|_| panic!("exclusive copied group edit transfer must retain its reserved slot"));
    store.displaced_retirements.release_owner_slots(history.rejected_owner).expect("exclusive copied group retains its exact rejected-owner reservation");
    if let Some(actor) = local_actor { retain_displaced_owner(&mut store.displaced_retirements, &mut displaced, Box::new(super::ArtifactStoreStringRetirement::new(actor))); }
    retain_displaced_owner(&mut store.displaced_retirements, &mut displaced, Box::new(super::ArtifactStoreStringRetirement::new(applied_edit_id)));
    let mut tail = revision.applied.pop().expect("copied group retains its new revision tail");
    tail.ledger_key = Some(ledger); revision.applied.push(tail);
    let content_revision = revision.revision(store.current_checkpoint_id.as_deref());
    *store.durable_group_root = Some(ArtifactStoreDurableGroupRootV1 {
        visibility, current: post, generation: store.generation + 1, content_revision,
        applied_edit_ids: applied, redo_edit_ids: crate::os_vcs::HistoryPageStack::empty(),
        last_projection_cause: Some(super::ArtifactProjectionCause::Apply), edit_sequence: authority.next_sequence_number,
        clock: next_clock, revision_accumulator: Some(revision), tail_undo_cache: Some((tail_edit_id, Arc::clone(&store.current))),
        authority: Some(authority), displaced_reservation: Some(displaced), retirement: Some(Box::new(StagedRootRetirement::new(Arc::clone(store.snapshot_retirement_factory.as_ref().expect("staged group retains its snapshot factory"))))), adopted: false,
    });
    Ok(())
}

fn retain_displaced_owner(store: &mut super::ArtifactStoreDisplacedRetirements, reservation: &mut super::ArtifactStoreDisplacedOwnerReservation, owner: Box<dyn super::ErasedSnapshotRetirement>) {
    if let Err(owner) = store.push_owner_reserved(reservation, owner) {
        store.push_reserved(owner);
    }
}

pub(super) fn abort_staged_store_member<P, Mutation>(store: &mut ArtifactStore<P, Mutation>, visibility: &Arc<crate::os_vcs::ArtifactGroupVisibility>) -> Result<(), DurableOwnedGroupDecisionError>
where
    P: ArtifactPack + Clone + ValueToValue + ValueFromValue + Send + Sync + 'static,
    Mutation: StoreMutation<P> + Clone + ValueToValue + ValueFromValue + Send + 'static,
{
    let Some(root) = store.durable_group_root.as_ref() else { return Ok(()) };
    if !Arc::ptr_eq(&root.visibility, visibility) || root.adopted || visibility.pending() || visibility.committed() {
        return Err(DurableOwnedGroupDecisionError::InvalidFrontier);
    }
    let mutation_factory = (*store.mutation_retirement_factory).clone().ok_or(DurableOwnedGroupDecisionError::InvalidOutcome)?;
    let snapshot_factory = (*store.snapshot_retirement_factory).clone().ok_or(DurableOwnedGroupDecisionError::InvalidOutcome)?;
    let edit = store.envelope.vcs.edits.abort_group_one(visibility).map_err(|()| DurableOwnedGroupDecisionError::InvalidFrontier)?.ok_or(DurableOwnedGroupDecisionError::InvalidOutcome)?;
    if store.envelope.vcs.edits.abort_group_one(visibility).map_err(|()| DurableOwnedGroupDecisionError::InvalidFrontier)?.is_some() {
        return Err(DurableOwnedGroupDecisionError::InvalidOutcome);
    }
    let cursor = store.envelope.cursor.as_mut().ok_or(DurableOwnedGroupDecisionError::InvalidFrontier)?.abort_group_owned(visibility).map_err(|()| DurableOwnedGroupDecisionError::InvalidFrontier)?;
    let mut root = store.durable_group_root.take().expect("validated aborted durable group root remains owned");
    let mut reservation = root.displaced_reservation.take().ok_or(DurableOwnedGroupDecisionError::InvalidOutcome)?;
    if let Some(retirement) = root.retirement.take() { retain_displaced_owner(&mut store.displaced_retirements, &mut reservation, retirement); }
    retain_displaced_owner(&mut store.displaced_retirements, &mut reservation, Box::new(super::ArtifactStoreDecodedEditRetirement::new(edit, mutation_factory)));
    retain_displaced_owner(&mut store.displaced_retirements, &mut reservation, Box::new(super::ArtifactStoreCursorRetirement::new(super::ArtifactCursor::from_owners(cursor))));
    if let Some(current) = root.current.take() {
        retain_displaced_owner(&mut store.displaced_retirements, &mut reservation, snapshot_factory.retire(current));
    }
    if !root.applied_edit_ids.is_empty() || root.applied_edit_ids.capacity() != 0 {
        retain_displaced_owner(&mut store.displaced_retirements, &mut reservation, Box::new(super::ArtifactStoreStringVectorRetirement::new(std::mem::replace(&mut root.applied_edit_ids, crate::os_vcs::HistoryPageStack::empty()))));
    }
    if !root.redo_edit_ids.is_empty() || root.redo_edit_ids.capacity() != 0 {
        retain_displaced_owner(&mut store.displaced_retirements, &mut reservation, Box::new(super::ArtifactStoreStringVectorRetirement::new(std::mem::replace(&mut root.redo_edit_ids, crate::os_vcs::HistoryPageStack::empty()))));
    }
    if let Some(revision) = root.revision_accumulator.take() {
        retain_displaced_owner(&mut store.displaced_retirements, &mut reservation, Box::new(super::ArtifactStoreRevisionAccumulatorRetirement::new(revision)));
    }
    if let Some((edit_id, snapshot)) = root.tail_undo_cache.take() {
        retain_displaced_owner(&mut store.displaced_retirements, &mut reservation, Box::new(super::ArtifactStoreStringRetirement::new(edit_id)));
        if !Arc::ptr_eq(&snapshot, &store.current) {
            retain_displaced_owner(&mut store.displaced_retirements, &mut reservation, snapshot_factory.retire(snapshot));
        }
    }
    if let Some(authority) = root.authority.take() {
        retain_displaced_owner(&mut store.displaced_retirements, &mut reservation, authority.retire());
    }
    store.displaced_retirements.release_owner_slots(reservation).map_err(|_| DurableOwnedGroupDecisionError::InvalidOutcome)?;
    Ok(())
}

/// 🪢️ Staging cached the pre-commit snapshot as this group's tail-undo entry
/// (`Arc::clone(&store.current)`), so the outgoing current and the incoming tail are the SAME
/// owner. Displacing it here would queue a retirement the tail cache still aliases, and the
/// close cursor drains displaced owners nine phases BEFORE `TailSnapshot` — it would meet an
/// `Arc` it cannot unwrap and answer `Blocked` forever. The tail cache keeps the owner instead,
/// exactly as the symmetric guards below and in `commit_document_roots_retained` do.
pub(super) fn adopt_staged_store_member<P, Mutation>(store: &mut ArtifactStore<P, Mutation>, visibility: &Arc<crate::os_vcs::ArtifactGroupVisibility>) -> Result<(), DurableOwnedGroupDecisionError>
where
    P: ArtifactPack + Clone + ValueToValue + ValueFromValue + Send + Sync + 'static,
    Mutation: StoreMutation<P> + Clone + ValueToValue + ValueFromValue + Send + 'static,
{
    let Some(root) = store.durable_group_root.as_ref() else { return Err(DurableOwnedGroupDecisionError::InvalidFrontier) };
    if !Arc::ptr_eq(&root.visibility, visibility) || root.adopted || !visibility.committed() {
        return Err(DurableOwnedGroupDecisionError::InvalidFrontier);
    }
    let factory = store.snapshot_retirement_factory.as_ref().ok_or(DurableOwnedGroupDecisionError::InvalidOutcome)?;
    if root.retirement.as_ref().and_then(|retirement| retirement.factory.as_ref()).is_none_or(|prepared| !Arc::ptr_eq(prepared, factory)) {
        return Err(DurableOwnedGroupDecisionError::InvalidOutcome);
    }
    store.envelope.vcs.edits.adopt_group(visibility).map_err(|()| DurableOwnedGroupDecisionError::InvalidFrontier)?;
    let displaced_cursor = store.envelope.cursor.as_mut().ok_or(DurableOwnedGroupDecisionError::InvalidFrontier)?.adopt_group_owned(visibility).map_err(|()| DurableOwnedGroupDecisionError::InvalidFrontier)?;
    let mut root = store.durable_group_root.take().expect("validated committed durable group root remains owned");
    let mut reservation = root.displaced_reservation.take().ok_or(DurableOwnedGroupDecisionError::InvalidOutcome)?;
    let mut retirement = root.retirement.take().ok_or(DurableOwnedGroupDecisionError::InvalidOutcome)?;
    retirement.cursor = Some(super::ArtifactStoreCursorRetirement::new(super::ArtifactCursor::from_owners(displaced_cursor)));
    retirement.applied = Some(super::ArtifactStoreStringVectorRetirement::new(std::mem::replace(&mut *store.applied_edit_ids, std::mem::replace(&mut root.applied_edit_ids, crate::os_vcs::HistoryPageStack::empty()))));
    retirement.redo = Some(super::ArtifactStoreStringVectorRetirement::new(std::mem::replace(&mut *store.redo_edit_ids, std::mem::replace(&mut root.redo_edit_ids, crate::os_vcs::HistoryPageStack::empty()))));
    let next_revision = root.revision_accumulator.take().ok_or(DurableOwnedGroupDecisionError::InvalidOutcome)?;
    retirement.revision = Some(super::ArtifactStoreRevisionAccumulatorRetirement::new(std::mem::replace(&mut *store.revision_accumulator, next_revision)));
    let previous_current = std::mem::replace(&mut *store.current, root.current.take().ok_or(DurableOwnedGroupDecisionError::InvalidOutcome)?);
    let next_tail = root.tail_undo_cache.take();
    if next_tail.as_ref().is_some_and(|(_, snapshot)| Arc::ptr_eq(snapshot, &previous_current)) {
        drop(previous_current);
    } else {
        retirement.snapshots[0] = Some(previous_current);
    }
    if let Some((edit_id, snapshot)) = store.tail_undo_cache.take() {
        retirement.tail_id = Some(super::ArtifactStoreStringRetirement::new(edit_id));
        if !Arc::ptr_eq(&snapshot, &store.current) {
            retirement.snapshots[1] = Some(snapshot);
        }
    }
    *store.tail_undo_cache = next_tail;
    retirement.report = Some(super::ArtifactStorePendingReportRetirement::new(std::mem::take(&mut *store.pending_report)));
    if let Some(authority) = root.authority.take() {
        retirement.authority = Some(super::canonical_edit::ArtifactStoreOneItemAuthorityRetirement::new(authority));
    }
    retain_displaced_owner(&mut store.displaced_retirements, &mut reservation, retirement);
    store.generation = root.generation;
    store.content_revision = root.content_revision;
    store.fold_frontier = None;
    store.edit_sequence = root.edit_sequence;
    store.clock = root.clock;
    store.last_projection_cause = root.last_projection_cause;
    store.displaced_retirements.release_owner_slots(reservation).map_err(|_| DurableOwnedGroupDecisionError::InvalidOutcome)?;
    root.adopted = true;
    *store.durable_group_root = Some(root);
    Ok(())
}

fn validate_adopted_store_member<P, Mutation>(store: &ArtifactStore<P, Mutation>, visibility: &Arc<crate::os_vcs::ArtifactGroupVisibility>) -> Result<(), DurableOwnedGroupDecisionError>
where
    P: Clone + ValueToValue + ValueFromValue,
    Mutation: StoreMutation<P> + Clone + ValueToValue + ValueFromValue,
{
    let root = store.durable_group_root.as_ref().ok_or(DurableOwnedGroupDecisionError::InvalidFrontier)?;
    if !root.adopted
        || !Arc::ptr_eq(&root.visibility, visibility)
        || root.current.is_some()
        || root.revision_accumulator.is_some()
        || root.tail_undo_cache.is_some()
        || root.authority.is_some()
        || root.retirement.is_some()
        || root.displaced_reservation.is_some()
        || !root.applied_edit_ids.is_empty()
        || !root.redo_edit_ids.is_empty()
    {
        return Err(DurableOwnedGroupDecisionError::InvalidOutcome);
    }
    Ok(())
}

fn clear_adopted_store_member<P, Mutation>(store: &mut ArtifactStore<P, Mutation>, visibility: &Arc<crate::os_vcs::ArtifactGroupVisibility>) -> Result<(), DurableOwnedGroupDecisionError>
where
    P: Clone + ValueToValue + ValueFromValue,
    Mutation: StoreMutation<P> + Clone + ValueToValue + ValueFromValue,
{
    validate_adopted_store_member(store, visibility)?;
    drop(store.durable_group_root.take());
    Ok(())
}

fn retire_unstaged_store_member<P, Mutation>(store: &mut ArtifactStore<P, Mutation>, outcome: DurableStoreBoundOutcomeV1<P, Mutation>) -> Result<(), DurableOwnedGroupDecisionError>
where
    P: ArtifactPack + Clone + ValueToValue + ValueFromValue + Send + Sync + 'static,
    Mutation: StoreMutation<P> + Clone + ValueToValue + ValueFromValue + Send + 'static,
{
    let mutation_factory = (*store.mutation_retirement_factory).clone().ok_or(DurableOwnedGroupDecisionError::InvalidOutcome)?;
    let snapshot_factory = (*store.snapshot_retirement_factory).clone().ok_or(DurableOwnedGroupDecisionError::InvalidOutcome)?;
    let mut reservation = store.displaced_retirements.reserve_owner_slots(6).map_err(|_| DurableOwnedGroupDecisionError::InvalidFrontier)?;
    let DurableStoreBoundOutcomeV1 { prepared, .. } = outcome;
    let ArtifactStoreOneItemPrepared { edit, post_snapshot, next_clock: _, edit_digest: _, local_actor, applied_edit_id, tail_edit_id, seal } = prepared;
    retain_displaced_owner(&mut store.displaced_retirements, &mut reservation, Box::new(super::ArtifactStoreDecodedEditRetirement::new(*edit, mutation_factory)));
    retain_displaced_owner(&mut store.displaced_retirements, &mut reservation, snapshot_factory.retire(post_snapshot));
    if let Some(actor) = local_actor {
        retain_displaced_owner(&mut store.displaced_retirements, &mut reservation, Box::new(super::ArtifactStoreStringRetirement::new(actor)));
    }
    retain_displaced_owner(&mut store.displaced_retirements, &mut reservation, Box::new(super::ArtifactStoreStringRetirement::new(applied_edit_id)));
    retain_displaced_owner(&mut store.displaced_retirements, &mut reservation, Box::new(super::ArtifactStoreStringRetirement::new(tail_edit_id)));
    retain_displaced_owner(&mut store.displaced_retirements, &mut reservation, seal.authority.retire());
    store.displaced_retirements.release_owner_slots(reservation).map_err(|_| DurableOwnedGroupDecisionError::InvalidOutcome)
}

