trait BatchOwner: Send {
    fn as_any(&self) -> &dyn Any;
    fn as_any_mut(&mut self) -> &mut dyn Any;
    fn close(&mut self, grant: RetainedCloneGrant) -> Result<RetainedCloneStep, ValueError>;
