struct TypedBatch<M: Send + 'static> {
    values: ManuallyDrop<Option<Vec<M>>>,
    retirement: ManuallyDrop<Option<Box<dyn BatchRetirement>>>,
    birth_bytes: usize,
    retire: fn(Vec<M>) -> Box<dyn BatchRetirement>,
